        <DialogActions>
          <Button onClick={() => removeError(error.id)} variant="contained">
            {t('errorDialogConfirm')}
          </Button>
        </DialogActions>
      </DialogContent>
    </Dialog>
  );
}

ErrorDialog.propTypes = {
  error: PropTypes.shape({
    id: PropTypes.string,
